<template>
  <div class="wrap">
    <div id="score" class="scoreboard">
      <div id="scoreDrag" class="header">
        <div class="title"><i class="fas fa-gamepad"></i>Players</div>
        <div class="players">{{ players.length }}</div>
      </div>
      <div class="search">
        <input @focus="isFocus(true)" @blur="isFocus(false)" v-model="filterInput" @input="filter($event)" type="text"
               autocomplete='off' spellcheck='false' placeholder="Filter" :disabled="disableInput">
      </div>
      <div class="list">
        <table>
          <colgroup>
            <col span="1" style="width: 7%;">
            <col span="2" style="width: 75%;">
          </colgroup>

          <thead>
          <tr>
            <th style="text-align: center;">LID</th>
            <th>NAME</th>
            <th style="text-align: center;">LEVEL</th>
            <th style="text-align: center;">PING</th>
          </tr>
          </thead>
          <tbody>
          <tr v-for="player in filteredPlayers" :key="player">
            <td :style="{ color: (player.color ? player.color : '') }" style="text-align: center;">
              {{ player.id }}
            </td>
            <td :style="{ color: (player.color ? player.color : '') }">{{ player.name }}</td>
            <td :style="{ color: (player.color ? player.color : '') }" style="text-align: center;">
              {{ player.level }}
            </td>
            <td :style="{ color: (player.color ? player.color : '') }" style="text-align: center;">
              {{ player.ping }}
            </td>
          </tr>
          </tbody>
        </table>
      </div>
      <div class="spacer"></div>
    </div>
  </div>
</template>

<script>
import $ from "jquery";
// eslint-disable-next-line no-unused-vars
import draggable from "jquery-ui/ui/widgets/draggable"


export default {
  name: 'Scoreboard',
  components: {},
  data() {
    return {
      disableInput: false,
      filterInput: "",
      filteredPlayers: [],
      players: []
    }
  },
  methods: {
    isFocus(value) {
      // eslint-disable-next-line no-undef
      mp.trigger('ScoreboardToggleTyping', value);
    },
    filter(event) {
      let input = event.target.value.replace(/\s/g, '');
      if (input.length < 1) return this.filteredPlayers = this.players;
      this.filteredPlayers = this.players.filter(player => player.name.toUpperCase().includes(input.toUpperCase())).sort(function (a, b) {
        return a - b;
      });
    },
    setPlayers(players) {
      this.playercount = players.length;
      let input = this.filterInput.replace(/\s/g, '');
      if (input.length > 0) {
        this.filteredPlayers = players.filter(player => player.name.toUpperCase().includes(input.toUpperCase()));
      } else {
        this.filteredPlayers = players.sort(function (a, b) {
          return a - b;
        });
      }

      this.players = players.sort(function (a, b) {
        return a - b;
      });
    }
  },
  mounted() {
    this.filteredPlayers = this.players.sort(function (a, b) {
      return a - b;
    });

    $('#score').draggable({
      handle: "#scoreDrag",
      containment: "body"
    });
  }
}
</script>

<style lang="scss">
$orange: rgb(255, 174, 0);
$blue: rgb(0, 151, 255);
$border-radius: 10px;
$score-bg: rgb(61, 61, 61);

.spacer {
  background: rgba($score-bg, 0.5);
  border-bottom-left-radius: $border-radius;
  border-bottom-right-radius: $border-radius;
  height: 10px;
}

/* width */
::-webkit-scrollbar {
  width: 5px;
}

/* Track */
::-webkit-scrollbar-track {
  background: rgba($score-bg, 0.5);
}

/* Handle */
::-webkit-scrollbar-thumb {
  background: #888;
  border-radius: $border-radius;
}

/* Handle on hover */
::-webkit-scrollbar-thumb:hover {
  background: #555;
}

.list {
  max-height: 400px;
  overflow-y: auto;

  table {
    width: 100%;
    background: rgba($score-bg, 0.5);

    th {
      text-align: left;
      font-size: 12px;
      color: rgba(241, 241, 241, 0.9);
      padding: 12px 8px;
      border-bottom: 1.5px solid rgba(241, 241, 241, 0.7);
    }

    td {
      padding: 4px 8px;
      color: rgba(241, 241, 241, 0.9);
      word-break: break-all;
    }
  }
}

.search {
  background: rgba($score-bg, 0.5);
  padding: 5px;
  border-bottom: 1.5px solid rgba(241, 241, 241, 0.7);

  input {
    width: 100%;
    border-radius: 2px;
    border: none;
    height: 25px;
    padding: 5px;
    font-size: 15px;
    background: rgba(lighten($score-bg, 50%), 0.4);
    color: rgba(lighten($score-bg, 70%), 0.7);

    &::placeholder {
      color: rgba(lighten($score-bg, 70%), 0.3);
    }

    &:focus {
      outline: none;
    }
  }
}

.header {
  background: linear-gradient(45deg, rgba($blue, 0.7) 0%, rgba($orange, 0.5) 100%);
  height: 50px;
  border-top-left-radius: $border-radius;
  border-top-right-radius: $border-radius;
  display: flex;
  align-items: center;
  padding: 0px 15px;
  border-bottom: 2px solid rgba(241, 241, 241, 0.7);

  .title {
    flex: 1;
    color: #f1f1f1;
    font-weight: 400;
    display: flex;
    align-items: center;

    .fas {
      margin-right: 5px;
    }
  }

  .players {
    font-weight: 400;
    color: #f1f1f1;
  }
}

.wrap {
  width: 100vw;
  height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  position: absolute;
}

.scoreboard {
  width: 350px;
  border-radius: $border-radius;
  display: flex;
  flex-direction: column;
  box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px;
}

* {
  padding: 0;
  margin: 0;
  font-family: 'Roboto', sans-serif;
  box-sizing: border-box;
  user-select: none;
}

body {
  //background: url('~@/assets/bg-test.png');
}
</style>
