<template>
  <ve-progress
      class="customProgress"
      :progress="compSpeed"
      :legend="speed"
      :half="true"
      :angle="0"
      fontSize="3.5rem"
      :size="200"
      dash="15"
      :thickness="10"
      :empty-thickness="5"
      color="rgba(91, 145, 254, 0.8)"
      emptyColor="rgba(255, 255, 255, 0.5)"
      legendClass="customLegend"
      :dot="{
        size: 20,
        backgroundColor: '#fff',
        width: '10px',
      }"
  >
    <template v-slot:legend-caption>
      <p class="customCaptio" slot="legend-caption">km/h</p>
    </template>
  </ve-progress>
</template>

<script>
export default {
  name: "Speedometer",
  computed: {
    compSpeed() {
      return (this.speed * 100) / this.maxspeed;
    }
  },
  data() {
    return {
      speed: 0,
      maxspeed: 100
    }
  }
}
</script>

<style lang="scss">
.customProgress {
  margin-bottom: -120px;
  * {
    overflow: visible;
  }
}

.customLegend {
  height: 57px;
  margin-top: -60px;
  z-index: 999;
  font-family: 'Nunito', sans-serif;
  color: rgba(255, 255, 255, 0.8);
  //text-shadow: 0px 0px 5px rgba(91, 145, 254, 0.5);
}

.customCaptio {
  font-family: 'Nunito', sans-serif;
  font-size: 17px;
  font-weight: bold;
  color: rgba(255, 255, 255, 0.8);
  //text-shadow: 0px 0px 5px rgba(91, 145, 254, 0.5);
}
</style>

